func ResolveEventDateHCM(tsMs int64, fallback time.Time) string {
	if tsMs > 0 {
		return time.UnixMilli(tsMs).In(locHCM).Format("2006-01-02")
	}
	if fallback.IsZero() {
		fallback = time.Now()
	}
	return fallback.In(locHCM).Format("2006-01-02")
}

